//! Derived human-readable memory (ADR-0008 Consolidation Contract step 4-5): `bank/*.md`,
//! `people/<slug>.md` and `groups/<slug>.md`, regenerated wholesale from the claims table.
//!
//! The files are a projection, not the citation target: a line cites the claim id and the stable
//! live-log URL of its source (line numbers in regenerated files would drift). Subjects come from
//! the model, so every file name is a strict slug checked before any path join (T-58.2-21).

use std::collections::{BTreeMap, HashSet};
use std::path::Path;

use anyhow::Context;

use crate::paths::Tier2Paths;
use crate::store::{ClaimRow, Store};

const HEADER: &str = "<!-- generated by ironhermes Tier 2 from tier2.db; edits are overwritten -->";
const MAX_SLUG: usize = 64;
/// Serialises `render_all` across processes and threads; lives at the tier2 root, outside the swept dirs.
pub const RENDER_LOCK_FILE: &str = "render.lock";

#[derive(Debug, Default, Clone, PartialEq, Eq)]
pub struct RenderReport {
    pub files_written: usize,
    pub files_removed: usize,
}

/// Lowercase ASCII alphanumerics kept; every other run of characters becomes one `-`; trimmed,
/// at most 64 chars; `unknown` when nothing is left.
pub fn slugify(name: &str) -> String {
    let mut out = String::new();
    for c in name.chars() {
        if c.is_ascii_alphanumeric() {
            out.push(c.to_ascii_lowercase());
        } else if !out.is_empty() && !out.ends_with('-') {
            out.push('-');
        }
    }
    out.truncate(MAX_SLUG);
    let out = out.trim_end_matches('-');
    if out.is_empty() {
        "unknown".into()
    } else {
        out.into()
    }
}

/// `^[a-z0-9][a-z0-9-]{0,63}$`
pub fn is_valid_slug(s: &str) -> bool {
    let mut chars = s.chars();
    s.len() <= MAX_SLUG
        && chars
            .next()
            .is_some_and(|c| c.is_ascii_lowercase() || c.is_ascii_digit())
        && chars.all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-')
}

fn line(c: &ClaimRow) -> String {
    let source = c.source_url.as_deref().unwrap_or("memory://unknown");
    format!("- {} [{}] ({source})", c.text, c.claim_id)
}

fn document(title: &str, lines: &[String]) -> String {
    let mut s = format!("# {title}\n\n{HEADER}\n\n");
    for l in lines {
        s.push_str(l);
        s.push('\n');
    }
    s
}

/// Write `dir/name` through a temp file in the same directory and a rename. Returns whether the
/// content changed. The temp file keeps the old file's permissions and is fsynced before the
/// rename, so a crash leaves the old or the new content, never a short file; it is removed when
/// the write fails (WR-04). Callers serialise writers of one `name` (render, append lock, lease).
pub(crate) fn write_atomic(dir: &Path, name: &str, content: &str) -> anyhow::Result<bool> {
    let path = dir.join(name);
    if std::fs::read_to_string(&path).is_ok_and(|old| old == content) {
        return Ok(false);
    }
    let tmp = dir.join(format!(".{name}.tmp"));
    let written = (|| {
        let mut f = std::fs::File::create(&tmp)?;
        if let Ok(meta) = std::fs::metadata(&path) {
            f.set_permissions(meta.permissions())?;
        }
        std::io::Write::write_all(&mut f, content.as_bytes())?;
        f.sync_all()?;
        std::fs::rename(&tmp, &path)
    })();
    if let Err(e) = written {
        let _ = std::fs::remove_file(&tmp);
        return Err(e).with_context(|| format!("writing {} via {}", path.display(), tmp.display()));
    }
    Ok(true)
}

/// Delete every `.md` / `.tmp` file in `dir` that is not in `keep`.
fn remove_stale(dir: &Path, keep: &HashSet<String>) -> anyhow::Result<usize> {
    let mut removed = 0;
    for entry in std::fs::read_dir(dir).with_context(|| format!("reading {}", dir.display()))? {
        let entry = entry?;
        let name = entry.file_name().to_string_lossy().into_owned();
        let derived = name.ends_with(".md") || name.ends_with(".tmp");
        if derived && entry.file_type()?.is_file() && !keep.contains(&name) {
            std::fs::remove_file(entry.path())?;
            removed += 1;
        }
    }
    Ok(removed)
}

/// Regenerate every derived file from the active, durable consolidation claims. Tier 1 mirrors
/// are not repeated here (they already live in MEMORY.md / USER.md).
pub fn render_all(store: &Store, paths: &Tier2Paths) -> anyhow::Result<RenderReport> {
    // Read inside the lock: temp names and the stale-.tmp sweep are then single-writer, and the
    // last renderer always renders the newest DB state. Blocks, so callers run it off async threads.
    let lock_path = paths.root.join(RENDER_LOCK_FILE);
    let _lock = crate::paths::lock_exclusive(&lock_path)
        .with_context(|| format!("locking {}", lock_path.display()))?;
    let claims = store.derived_claims()?;
    let mut report = RenderReport::default();

    let mut bank: BTreeMap<&str, Vec<String>> = BTreeMap::new();
    let mut people: BTreeMap<String, (String, Vec<String>)> = BTreeMap::new();
    let mut groups: BTreeMap<String, (String, Vec<String>)> = BTreeMap::new();
    for c in &claims {
        if c.subject == "user" {
            let file = match c.kind.as_str() {
                "world" => "world.md",
                "experience" => "experience.md",
                "opinion" => "opinions.md",
                "reflection" => "reflections.md",
                _ => continue,
            };
            bank.entry(file).or_default().push(line(c));
        } else if let Some((map, name)) = c
            .subject
            .strip_prefix("person:")
            .map(|n| (&mut people, n))
            .or_else(|| c.subject.strip_prefix("group:").map(|n| (&mut groups, n)))
        {
            map.entry(slugify(name))
                .or_insert_with(|| (name.trim().to_string(), Vec::new()))
                .1
                .push(line(c));
        }
    }

    let mut bank_names = HashSet::new();
    for (file, title) in [
        ("world.md", "World"),
        ("experience.md", "Experience"),
        ("opinions.md", "Opinions"),
        ("reflections.md", "Reflections"),
    ] {
        let lines = bank.remove(file).unwrap_or_default();
        report.files_written +=
            usize::from(write_atomic(&paths.bank, file, &document(title, &lines))?);
        bank_names.insert(file.to_string());
    }
    report.files_removed += remove_stale(&paths.bank, &bank_names)?;

    for (dir, map) in [(&paths.people, &people), (&paths.groups, &groups)] {
        let mut keep = HashSet::new();
        for (slug, (title, lines)) in map {
            anyhow::ensure!(is_valid_slug(slug), "refusing invalid slug {slug:?}");
            let name = format!("{slug}.md");
            let title = if title.is_empty() { slug } else { title };
            report.files_written += usize::from(write_atomic(dir, &name, &document(title, lines))?);
            keep.insert(name);
        }
        report.files_removed += remove_stale(dir, &keep)?;
    }
    Ok(report)
}
